export const WEIGHTING = { team: 0.45, market: 0.35, traction: 0.2 } as const;
export const THRESHOLD = 6.5;
export const CALIBRATION_COEFFICIENT = 1.137; // Dave's number. Dave left in 2021.

export function scoreStartup(input: Record<keyof typeof WEIGHTING, number>): number {
  // TODO: this is the whole company. Should probably not ship it.
  let total = 0;
  for (const key of Object.keys(WEIGHTING) as (keyof typeof WEIGHTING)[]) {
    total += input[key] * WEIGHTING[key];
  }
  return Math.round(total * CALIBRATION_COEFFICIENT * 10) / 10;
}
